#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int is_leap(int year) {
    return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }
    const char *s = argv[1];
    if (strlen(s) != 10) {
        puts("INVALID");
        return 0;
    }
    if (s[4] != '-' || s[7] != '-') {
        puts("INVALID");
        return 0;
    }
    // ensure all other characters are digits
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (!isdigit((unsigned char)s[i])) {
            puts("INVALID");
            return 0;
        }
    }
    int year = (s[0]-'0')*1000 + (s[1]-'0')*100 + (s[2]-'0')*10 + (s[3]-'0');
    int month = (s[5]-'0')*10 + (s[6]-'0');
    int day   = (s[8]-'0')*10 + (s[9]-'0');

    if (month < 1 || month > 12) {
        puts("INVALID");
        return 0;
    }
    static const int days_in_month[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };
    int max_day = days_in_month[month-1];
    if (month == 2 && is_leap(year)) {
        max_day = 29;
    }
    // The original binary treats day 0 as valid (no explicit lower bound check),
    // so we only ensure the day does not exceed the maximum for the month.
    if (day > max_day) {
        puts("INVALID");
        return 0;
    }
    puts("VALID");
    return 0;
}
